struct se_portal_group *create_target_portal_group(struct se_wwn *wwn,
                                                   struct config_group *group,
                                                   const char *name)
{
    struct se_portal_group *tpg;
    char *prefix = "tpgt_";
    int ret;

    if (strncmp(name, prefix, strlen(prefix)) != 0) {
        return ERR_PTR(-EINVAL);
    }

    tpg = kzalloc(sizeof(*tpg), GFP_KERNEL);
    if (!tpg) {
        return ERR_PTR(-ENOMEM);
    }

    tpg->tpg_wwn = wwn;
    tpg->tpg_group = group;

    ret = kstrtoul(name + strlen(prefix), 10, &tpg->tpg_id);
    if (ret < 0) {
        kfree(tpg);
        return ERR_PTR(ret);
    }

    mutex_lock(&tpg_mutex);
    ret = register_se_portal_group(tpg);
    if (ret < 0) {
        mutex_unlock(&tpg_mutex);
        kfree(tpg);
        return ERR_PTR(ret);
    }

    list_add(&tpg->tpg_list, &tpg_list);
    mutex_unlock(&tpg_mutex);

    return tpg;
}
